 .rail{background:#33291f;color:#f3dfbb;border-right:3px solid #b99558;display:flex;flex-direction:column;align-items:center;padding:10px 5px;gap:12px}.brand{font-size:12px;font-weight:900;writing-mode:vertical-rl;letter-spacing:3px;color:#92def2}.railbtn{width:48px;height:48px;border:1px solid #a88a5a;background:#51412f;color:#e8d19d;cursor:pointer}.railbtn b{display:block;font-size:17px}.railbtn span{font-size:8px}.railbtn.on{background:#87cfdf;color:#183239}
