+.modal{position:absolute;inset:0;background:rgba(38,38,35,.55);z-index:10;display:flex;align-items:center;justify-content:center}.modal.off{display:none}.dialog{width:min(520px,88%);background:#eee1c5;border:4px solid #765f45;padding:16px;box-shadow:8px 8px 0 rgba(40,36,29,.35)}.dialog h2{margin:0 0 12px}.row{display:grid;grid-template-columns:120px 1fr;gap:8px;margin:8px 0}.dialog input{border:2px solid #877557;background:#fff9e9;padding:8px}.dialog button{border:2px solid #80684e;background:#82bec9;height:36px;padding:0 14px;margin-right:6px}.dialog .start{background:#d5b878}.roomlist{max-height:110px;overflow:auto;border:1px solid #a58d69;background:#f8efd9;margin:8px 0}.roomitem{height:34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px dotted #baa98b;padding:3px 6px;font-size:12px}.roomitem button{height:26px;padding:0 10px}.toast{position:absolute;z-index:20;left:50%;top:18%;transform:translateX(-50%);background:#29261f;color:#fff4ca;padding:8px 14px;border:2px solid #d6b872;opacity:0;transition:.2s}.toast.show{opacity:1}
 @media(max-width:760px){.app{grid-template-columns:48px 1fr}.sidebar{position:absolute;right:0;top:48px;bottom:42px;width:170px;z-index:5}.side{grid-template-columns:44px 1fr 44px}.zones{grid-template-columns:repeat(5,minmax(38px,54px));gap:3px}.board{padding:3px}.identity:nth-child(3){display:none}.handcard{width:46px;height:66px}.room{display:none}.zone{min-height:52px}}
