 <nav class="rail"><div class="brand">DUELINKS</div><button class="railbtn on"><b>⚔</b><span>DUEL</span></button><button class="railbtn" id="lobbyBtn"><b>⌂</b><span>ROOM</span></button><button class="railbtn"><b>▤</b><span>DECK</span></button></nav>

