 function toast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),900)}
 function render(){ $('#pLp').textContent=lp[0]+' LP';$('#eLp').textContent=lp[1]+' LP';$('#turnText').textContent='TURN '+turn+' — '+(enemyTurn?'RIVAL':'PLAYER');$('#phaseText').textContent=phase }
 $('#lobbyBtn').onclick=()=>$('#modal').classList.remove('off');
 $('#offlineBtn').onclick=()=>start(false);$('#onlineBtn').onclick=()=>start(true);
+$('#roomList').onclick=e=>{let b=e.target.closest('[data-room]');if(!b)return;$('#roomIn').value=b.dataset.room;start(true)};
 function start(online){ $('#pName').textContent=$('#nameIn').value||'PLAYER';$('#roomName').textContent='ROOM / '+$('#roomIn').value||'SOLO';$('#modal').classList.add('off');addLog(online?'オンラインルームを作成しました。':'オフラインデュエルを開始。');toast('DUEL START') }
 $('#chat').onkeydown=e=>{if(e.key==='Enter'&&e.target.value.trim()){addLog($('#pName').textContent+': '+e.target.value);e.target.value=''}};
 function summonCard(card){if(enemyTurn)return;let empty=[...document.querySelectorAll('#ownZones .zone')].find(z=>!z.firstChild);if(!empty)return toast('モンスターゾーンが満杯');empty.innerHTML=`<div class="mini ${card==='lac'?'blue':'dark'}"><span>${card==='lac'?'Ujｽﾗｼﾍｱﾝｽｱｲlacwin11':'ビースト相闘剣士'}</span><b class="atk">ATK ${card==='lac'?bonus:2600}</b></div>`;if(card==='lac')selected=empty;addLog((card==='lac'?'Ujｽﾗｼﾍｱﾝｽｱｲlacwin11':'ビースト相闘剣士')+'を召喚しました。');toast('召喚成功')}
 $('#hand').onclick=e=>{let c=e.target.closest('.handcard');if(!c)return;document.querySelectorAll('.handcard').forEach(x=>x.classList.remove('selected'));c.classList.add('selected');selected=c.dataset.card};

